package com.tuap.backend.auth;
import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*; import java.time.*; import java.util.*; import org.junit.jupiter.api.*; import org.mockito.*; import com.tuap.backend.dominio.entidades.PendingSocialAuth; import com.tuap.backend.persistencia.PendingSocialAuthDAO;
class PendingSocialAuthServiceTest { @Mock PendingSocialAuthDAO dao; PendingSocialAuthService service; ArgumentCaptor<PendingSocialAuth> cap; @BeforeEach void set(){MockitoAnnotations.openMocks(this);service=new PendingSocialAuthService(dao,Clock.fixed(Instant.parse("2026-01-01T00:00:00Z"),ZoneOffset.UTC));cap=ArgumentCaptor.forClass(PendingSocialAuth.class);when(dao.save(any())).thenAnswer(i->i.getArgument(0));}
 @Test void issuesGoogleLegacyAndAppleNullable(){String g=service.issue(new VerifiedGoogleIdentity("g","g@test",true,"N","G","F"));verify(dao).save(cap.capture());assertEquals(AuthProvider.GOOGLE,cap.getValue().getProvider());assertNotEquals(g,cap.getValue().getTokenHash());String a=service.issue(new VerifiedSocialIdentity(AuthProvider.APPLE,"a",null,null,null));verify(dao,times(2)).save(cap.capture());assertEquals(AuthProvider.APPLE,cap.getValue().getProvider());assertNull(cap.getValue().getVerifiedEmail());}
 @Test void consumesPreservingProviderAndRejectsReplay(){PendingSocialAuth p=new PendingSocialAuth("x",AuthProvider.APPLE,"a",null,null,Instant.parse("2026-01-01T00:15:00Z"),Instant.now());when(dao.findByTokenHash(any())).thenReturn(Optional.of(p));assertEquals(AuthProvider.APPLE,service.consume("raw").getProvider());assertThrows(InvalidPendingSocialAuthException.class,()->service.consume("raw"));}
 @Test void rejectsInvalidAndLocal(){when(dao.findByTokenHash(any())).thenReturn(Optional.empty());assertThrows(InvalidPendingSocialAuthException.class,()->service.consume("raw"));assertThrows(IllegalArgumentException.class,()->new VerifiedSocialIdentity(AuthProvider.LOCAL,"x",null,null,null));assertThrows(IllegalArgumentException.class,()->new VerifiedSocialIdentity(AuthProvider.APPLE," ",null,null,null));}
}
